const {$:unused}=Object;const $=s=>document.querySelector(s),fmt=(v,d=0)=>Number(v).toLocaleString(I18n.locale,{maximumFractionDigits:d}),colors=['#235647','#7a9b70','#c5d49f','#dfbb75'];let tab='overview',scenario={price:0,volume:0,food:0,labor:0},market='hcm';let invoices=[];try{invoices=JSON.parse(localStorage.getItem('bep-invoices')||'[]')}catch{}const titles={overview:['Bức tranh kinh doanh của bạn','Từ doanh thu đến lợi nhuận, mọi con số đều có câu chuyện.'],costs:['Hiểu rõ từng khoản chi','Chi phí minh bạch là khởi đầu của lợi nhuận bền vững.'],simulate:['Thử một thay đổi. Thấy ngay tác động.','Khám phá các phương án kinh doanh trước khi đưa ra quyết định.'],forecast:['Chuẩn bị cho những tháng sắp tới','Lập kế hoạch từ những giả định rõ ràng, có thể điều chỉnh.'],market:['Góc nhìn thị trường nguyên liệu','So sánh giá theo khu vực và theo dõi chi phí mua hàng.'],invoices:['Sổ giao dịch của nhà hàng','Ghi nhận giao dịch thử nghiệm, sẵn sàng cho bước tích hợp dữ liệu.'],research:['Nền tảng cho những quyết định tốt','Nguồn mở đã kiểm tra và lộ trình phát triển hệ thống tài chính.']};
function base(){return Finance.total($('#branch').value==='all'?Finance.branches:[Finance.branches[+$('#branch').value]])}function results(){return Finance.calc(base())}function toast(t){$('#toast').textContent=t;$('#toast').style.display='block';setTimeout(()=>$('#toast').style.display='none',3500)}
function kpis(b){let r=Finance.calc(b);return `<div class="kpis"><div class="card"><div class="kpi-title">Doanh thu thuần <span>↗</span></div><div class="kpi-number">${fmt(r.revenue)}<small>triệu ₫</small></div><div class="kpi-foot">Sau giảm giá · chưa gồm VAT</div></div><div class="card"><div class="kpi-title">Tổng chi phí vận hành <span>◷</span></div><div class="kpi-number">${fmt(r.cost)}<small>triệu ₫</small></div><div class="kpi-foot">Bao gồm thuê mặt bằng: <strong>${fmt(b.rent)} triệu</strong></div></div><div class="card"><div class="kpi-title">Lợi nhuận vận hành <span>↗</span></div><div class="kpi-number">${fmt(r.profit)}<small>triệu ₫</small></div><div class="kpi-foot">Trước khấu hao, lãi vay và thuế</div></div><div class="card"><div class="kpi-title">Biên lợi nhuận vận hành <span>◉</span></div><div class="kpi-number">${fmt(r.margin,1)}<small>%</small></div><div class="kpi-foot">Mỗi 100₫ doanh thu giữ lại ${fmt(r.margin,1)}₫</div></div></div>`}
function lineChart(rev,profit,future=false){const W=600,H=220,top=15,bot=180,max=Math.max(...rev)*1.18;const pt=(a)=>a.map((v,i)=>`${45+i*52},${bot-v/max*(bot-top)}`).join(' ');let grid=[0,.25,.5,.75,1].map(n=>`<line x1="38" x2="575" y1="${bot-n*(bot-top)}" y2="${bot-n*(bot-top)}" stroke="#edf0e9" stroke-dasharray="3 4"/><text x="0" y="${bot-n*(bot-top)+4}">${fmt(n*max)}</text>`).join('');return `<svg class="chart" viewBox="0 0 ${W} ${H}" role="img" aria-label="Biểu đồ doanh thu và lợi nhuận theo tháng">${grid}${future?'<rect x="435" y="10" width="140" height="170" fill="#f2f5e9"/><text x="450" y="28">Kịch bản</text>':''}<polygon points="45,180 ${pt(rev)} 565,180" fill="#174b4008"/><polyline points="${pt(rev)}" fill="none" stroke="#285a48" stroke-width="2.5" ${future?'stroke-dasharray="6 3"':''}/><polyline points="${pt(profit)}" fill="none" stroke="#b9cf8b" stroke-width="2.5"/>${rev.map((v,i)=>`<circle cx="${45+i*52}" cy="${bot-v/max*(bot-top)}" r="3.5" fill="white" stroke="#285a48" stroke-width="2"><title>Tháng ${i+1}: doanh thu ${fmt(v)} triệu; lợi nhuận ${fmt(profit[i])} triệu</title></circle><text x="${36+i*52}" y="207">${I18n.monthLabel(i+1,undefined,true)}</text>`).join('')}</svg><div class="legend"><span><i class="dot"></i>Doanh thu</span><span><i class="dot" style="background:#b9cf8b"></i>Lợi nhuận vận hành</span><span>Đơn vị: triệu ₫</span></div>`}
function costCard(b){let r=Finance.calc(b),vals=[b.food,b.labor,b.rent,b.other],names=['Nguyên liệu','Nhân sự','Thuê mặt bằng','Vận hành khác'],acc=0;let gradient=vals.map((v,i)=>{let st=acc;acc+=v/r.cost*100;return `${colors[i]} ${st}% ${acc}%`}).join(',');return `<div class="card"><div class="card-head"><div><h2>Cơ cấu chi phí</h2><p>Mỗi khoản chi, một góc nhìn</p></div><span class="pill">Tháng 11</span></div><div class="donut-wrap"><div class="donut" style="background:conic-gradient(${gradient})" role="img" aria-label="Tỷ trọng chi phí"><div><b>${fmt(r.cost)}</b><small>triệu đồng</small></div></div><div class="cost-legend">${vals.map((v,i)=>`<div><span><i class="dot" style="background:${colors[i]}"></i>${names[i]}</span><b>${fmt(v/r.cost*100,1)}%</b></div>`).join('')}</div></div><div class="insight">⌂ Thuê mặt bằng chiếm <b>${fmt(b.rent/b.revenue*100,1)}% doanh thu</b>. Theo dõi cùng năng suất bán hàng từng địa điểm.</div></div>`}
function branchesTable(){return `<div class="card"><div class="card-head"><div><h2>Hiệu quả từng chi nhánh</h2><p>Nhìn rõ điểm mạnh, tìm đúng cơ hội</p></div><span class="pill">3 chi nhánh</span></div><div class="table-wrap"><table><thead><tr><th>Chi nhánh</th><th>Doanh thu</th><th>Thuê mặt bằng</th><th>Lợi nhuận</th><th>Biên LN</th></tr></thead><tbody>${Finance.branches.map(b=>{let r=Finance.calc(b);return `<tr><td><strong>${b.name}</strong><small>${b.city}</small></td><td>${fmt(b.revenue)}</td><td>${fmt(b.rent)}</td><td><strong>${fmt(r.profit)}</strong></td><td><span class="status ${r.margin<16?'amber':''}">${fmt(r.margin,1)}%</span></td></tr>`}).join('')}</tbody></table></div></div>`}
function overview(){let b=base(),r=results();const seasonal=[.79,.72,.88,.85,.93,.94,.98,1.01,.96,1.04,1];let rev=seasonal.map(x=>x*b.revenue),prof=seasonal.map(x=>Finance.calc(b,{volume:(x-1)*100}).profit);return `<div class="banner"><span class="symbol">↗</span><div><b>Hiểu hôm nay. Vững bước ngày mai.</b><p>${$('#branch').selectedOptions[0].text}: doanh thu hòa vốn khoảng ${fmt(r.breakeven)} triệu ₫/tháng theo cơ cấu chi phí hiện tại.</p></div><span class="tag">Tổng quan tháng 11</span></div>${kpis(b)}<div class="grid"><div class="card"><div class="card-head"><div><h2>Doanh thu & lợi nhuận</h2><p>Diễn biến 11 tháng · Chuỗi dữ liệu minh họa</p></div><span class="pill">Năm 2026</span></div>${lineChart(rev,prof)}</div>${costCard(b)}</div><div class="grid">${branchesTable()}<div class="card"><div class="card-head"><div><h2>Điều đáng chú ý</h2><p>Những gợi ý để bắt đầu hành động</p></div><span>✧</span></div><div class="recommend"><div class="rec"><span>⌂</span><div><b>Mặt bằng cần đi cùng doanh thu</b><p>Thảo Điền đang dành 12% doanh thu cho tiền thuê; hãy thử các kịch bản thương lượng hợp đồng.</p><a data-go="simulate">Thử mô phỏng →</a></div></div><div class="rec"><span>↗</span><div><b>Chủ động trước biến động giá mua</b><p>So sánh giá nguyên liệu giữa các khu vực với cùng đơn vị đo.</p><a data-go="market">Xem thị trường minh họa →</a></div></div><div class="rec"><span>✓</span><div><b>Kiểm tra số liệu trước quyết định</b><p>Demo dùng dữ liệu giả lập. Dữ liệu thật cần đối soát hóa đơn, tồn kho và doanh thu.</p><a data-go="research">Xem phương pháp →</a></div></div></div></div></div>`}
function costs(){let b=base(),r=results();return `${kpis(b)}<div class="two">${costCard(b)}<div class="card"><h2>Chi phí theo nhóm</h2><p>Tỷ trọng trên tổng chi phí vận hành</p>${['food','labor','rent','other'].map((k,i)=>`<div class="barrow"><span>${['Nguyên liệu','Nhân sự','Thuê mặt bằng','Vận hành khác'][i]}</span><div class="track"><i style="width:${b[k]/r.cost*100}%;background:${colors[i]}"></i></div><b>${fmt(b[k])} triệu</b></div>`).join('')}<div class="insight">Giá vốn nguyên liệu = tồn đầu kỳ + nhập trong kỳ − tồn cuối kỳ. Các số liệu mẫu đã giả định điều chỉnh tồn kho.</div></div></div><div class="card" style="margin-top:20px"><h2>Mặt bằng & nghĩa vụ hợp đồng</h2><div class="table-wrap"><table><thead><tr><th>Địa điểm</th><th>Tiền thuê / tháng</th><th>Tỷ lệ doanh thu</th><th>Giả định hợp đồng</th></tr></thead><tbody>${Finance.branches.map(b=>`<tr><td>${b.name}</td><td>${fmt(b.rent)} triệu ₫</td><td>${fmt(b.rent/b.revenue*100,1)}%</td><td>Chi phí phân bổ tháng · chưa gồm tiền cọc</td></tr>`).join('')}</tbody></table></div><p class="muted">Tiền cọc không ghi nhận ngay vào chi phí thuê. Bản triển khai thật cần theo dõi trả trước, lịch tăng giá, công nợ và dòng tiền thanh toán.</p></div>`}
function slider(k,label,min,max,value,suffix,help){return `<div class="field"><label for="${k}">${label}<b id="${k}Val">${fmt(value,1)}${suffix}</b></label><input id="${k}" data-scenario="${k}" type="range" min="${min}" max="${max}" step="${k==='rent'?1:.5}" value="${value}"><small>${help}</small></div>`}
function simulate(){let b=base();if(scenario.rent===undefined)scenario.rent=b.rent;return `<div class="two"><div class="card"><div class="card-head"><div><h2>Điều chỉnh kế hoạch của bạn</h2><p>Thay đổi giả định, kết quả cập nhật tức thì</p></div><button class="outline" id="reset">Đặt lại</button></div>${slider('price','Thay đổi giá bán',-15,20,scenario.price,'%','Áp dụng đồng đều cho giá bán bình quân.')}${slider('volume','Thay đổi lượng bán',-30,30,scenario.volume,'%','Giả định độc lập: tăng giá có thể làm giảm số đơn.')}${slider('food','Biến động giá nguyên liệu',-20,30,scenario.food,'%','Giữ nguyên định lượng và chất lượng món ăn.')}${slider('rent','Tiền thuê mặt bằng / tháng',0,Math.ceil(b.rent*1.7),scenario.rent,' triệu ₫','Chi phí cố định, không tự giảm khi lượng bán giảm.')}${slider('labor','Thay đổi chi phí nhân sự',-15,20,scenario.labor,'%','Cần bảo đảm nhân sự tối thiểu khi áp dụng thực tế.')}</div><div><div class="card"><h2>Kết quả kịch bản</h2><div id="simResult"></div><div class="actions"><button class="primary" id="saveScenario">Lưu kịch bản trên thiết bị</button><button class="outline" id="loadScenario">Mở kịch bản đã lưu</button></div></div><div class="card" style="margin-top:20px"><h2>Điều gì đứng sau con số?</h2><p class="muted">Doanh thu = doanh thu gốc × hệ số giá × hệ số lượng bán.<br>Nguyên liệu thay đổi theo giá mua và lượng bán. 40% chi phí khác biến đổi theo lượng bán; 60% còn lại cố định. Thuê mặt bằng và nhân sự cố định theo giả định bạn chọn.</p><div class="insight">Đây là phân tích độ nhạy, chưa phải tối ưu bằng OR-Tools. Không tự áp dụng giá hoặc cắt giảm nhân sự.</div></div></div></div>`}
function updateSim(){let b=base(),r=Finance.calc(b,scenario),old=Finance.calc(b);$('#simResult').innerHTML=`<div class="result"><span>Lợi nhuận vận hành dự kiến / tháng</span><b>${fmt(r.profit,1)} <small style="font-size:14px">triệu ₫</small></b><p>${r.profit>=old.profit?'Tăng':'Giảm'} ${fmt(Math.abs(r.profit-old.profit),1)} triệu ₫ so với hiện tại</p></div><table><tr><th>Chỉ số</th><th>Hiện tại</th><th>Kịch bản</th></tr>${[['Doanh thu',old.revenue,r.revenue],['Tổng chi phí',old.cost,r.cost],['Thuê mặt bằng',old.rent,r.rent],['Biên lợi nhuận (%)',old.margin,r.margin],['Doanh thu hòa vốn',old.breakeven,r.breakeven]].map(x=>`<tr><td>${x[0]}</td><td>${fmt(x[1],1)}</td><td><b>${x[2]===null?'Không đạt':fmt(x[2],1)}</b></td></tr>`).join('')}</table><p class="muted">Lợi nhuận trước khấu hao, lãi vay và thuế. Không đồng nghĩa với dòng tiền.</p>`}
function forecast(){return `<div class="banner"><span class="symbol">⌁</span><div><b>Lên kế hoạch theo nhiều khả năng</b><p>Kịch bản mùa vụ minh họa; chưa huấn luyện mô hình dự báo trên dữ liệu nhà hàng thật.</p></div></div><div class="card"><div class="card-head"><div><h2>Doanh thu & lợi nhuận theo mùa</h2><p>Tháng 1–11 minh họa; tháng 12 là kịch bản</p></div><select id="forecastMode" aria-label="Kịch bản dự báo"><option value="0">Cơ sở</option><option value="-10">Thận trọng: lượng bán −10%</option><option value="10">Thuận lợi: lượng bán +10%</option></select></div><div id="forecastChart"></div></div><div id="forecastTable" class="card" style="margin-top:20px"></div><div class="insight" style="margin-top:15px">Chưa có khoảng tin cậy thống kê: ba kịch bản là giả định của người lập kế hoạch. Bước tiếp theo: dữ liệu POS, ngày lễ và kiểm định dự báo theo thời gian.</div>`}
function updateForecast(){let b=base(),n=+$('#forecastMode').value;let s=[.79,.72,.88,.85,.93,.94,.98,1.01,.96,1.04,1,1.12*(1+n/100)];$('#forecastChart').innerHTML=lineChart(s.map(v=>b.revenue*v),s.map(v=>Finance.calc(b,{volume:(v-1)*100}).profit),true);$('#forecastTable').innerHTML=`<h2>Kế hoạch 3 tháng gần tới</h2><div class="table-wrap"><table><thead><tr><th>Tháng</th><th>Giả định lượng bán so với T11</th><th>Doanh thu</th><th>Chi phí thuê</th><th>Lợi nhuận vận hành</th></tr></thead><tbody>${[1.12,1.08,.87].map((v,i)=>{let vol=(v*(1+n/100)-1)*100,r=Finance.calc(b,{volume:vol});return `<tr><td>${['12/2026','01/2027','02/2027'][i]}</td><td>${fmt(vol,1)}%</td><td>${fmt(r.revenue,1)}</td><td>${fmt(b.rent)}</td><td>${fmt(r.profit,1)}</td></tr>`}).join('')}</tbody></table></div>`}
function marketView(){const names={hcm:'TP. Hồ Chí Minh',danang:'Đà Nẵng',hanoi:'Hà Nội'};let factor={hcm:1,danang:.94,hanoi:1.04}[market];return `<div class="two"><div class="card"><div class="card-head"><div><h2>Chọn khu vực khảo sát</h2><p>Sơ đồ vị trí minh họa · Việt Nam</p></div><select id="marketSelect" aria-label="Khu vực">${Object.entries(names).map(([k,v])=>`<option value="${k}" ${k===market?'selected':''}>${v}</option>`).join('')}</select></div><div class="map"><svg viewBox="0 0 500 300" aria-label="Sơ đồ khu vực Việt Nam"><defs><pattern id="p" width="30" height="30" patternUnits="userSpaceOnUse"><path d="M30 0H0V30" fill="none" stroke="#dbe4d3" stroke-width=".8"/></pattern></defs><rect width="500" height="300" fill="url(#p)"/><path d="M213 25 L250 38 273 70 258 91 269 116 285 136 294 165 315 190 308 222 290 245 250 264 229 249 266 222 281 199 265 168 258 142 241 121 228 93 207 79 190 51Z" fill="#cad9bb" stroke="#a6bd95" stroke-width="2"/><path d="M30 250Q170 40 440 160M100 290Q280 180 400 30" stroke="white" stroke-width="3" fill="none" opacity=".6"/></svg><button data-city="hanoi" style="top:18%;left:40%">● Hà Nội</button><button data-city="danang" style="top:47%;left:53%">● Đà Nẵng</button><button data-city="hcm" style="top:77%;left:40%">● TP.HCM</button><div class="map-note">Sơ đồ minh họa, không dùng để dẫn đường</div></div></div><div class="card"><div class="card-head"><div><h2>Giá tham khảo · ${names[market]}</h2><p>Dữ liệu giả lập · VNĐ/kg · không phải báo giá trực tiếp</p></div></div><table><thead><tr><th>Nguyên liệu</th><th>Giá mẫu</th><th>Biến động mẫu / tuần</th></tr></thead><tbody>${[['Thịt bò',245000,4.2],['Thịt heo',112000,-1.5],['Thịt gà',78000,2.1],['Gạo',22000,.8],['Rau cải',28000,-3.2]].map(x=>`<tr><td>${x[0]}</td><td>${fmt(x[1]*factor)} ₫</td><td style="color:${x[2]>0?'#b08b4d':'#67864f'}">${x[2]>0?'↑':'↓'} ${fmt(Math.abs(x[2]),1)}%</td></tr>`).join('')}</tbody></table><p class="muted">Nguồn: bộ dữ liệu minh họa của demo. Chưa kết nối nhà cung cấp; chưa gồm thuế, vận chuyển hoặc quy cách phẩm cấp. Chưa hỗ trợ giá thời gian thực toàn cầu.</p></div></div>`}
function invoicesView(){return `<div class="two"><div class="card"><h2>Ghi nhận giao dịch thử nghiệm</h2><p>Chỉ lưu tại trình duyệt; chưa đưa vào báo cáo tổng quan.</p><form id="invoiceForm"><div class="field"><label for="invoiceName">Mã hóa đơn</label><input id="invoiceName" required maxlength="60" placeholder="VD: HD-2026-001"></div><div class="form-grid"><div class="field"><label for="invoiceType">Loại giao dịch</label><select id="invoiceType"><option value="Chi phí">Chi phí</option><option value="Doanh thu">Doanh thu</option></select></div><div class="field"><label for="invoiceAmount">Số tiền (VND)</label><input id="invoiceAmount" type="number" min="1" max="1000000000000" required></div><div class="field"><label for="invoiceBranch">Chi nhánh</label><select id="invoiceBranch">${Finance.branches.map(b=>`<option value="${b.name}">${b.name}</option>`).join('')}</select></div><div class="field"><label for="invoiceDate">Ngày giao dịch</label><input id="invoiceDate" type="date" required value="2026-11-08"></div></div><button class="primary">Lưu giao dịch mẫu</button></form><p class="muted">Chưa hỗ trợ OCR ảnh/PDF hoặc đồng bộ POS. Bản thật sẽ có bước xác nhận và đối soát trước khi ghi sổ.</p></div><div class="card"><h2>Nguyên tắc ghi nhận dữ liệu</h2><div class="rec" style="margin-top:20px"><span>01</span><div><b>Nhận dữ liệu</b><p>Hóa đơn nhà cung cấp, doanh số POS, bảng lương và hợp đồng thuê.</p></div></div><div class="rec" style="margin-top:20px"><span>02</span><div><b>Kiểm tra & đối soát</b><p>Phát hiện trùng số hóa đơn, kiểm tra thuế và phân bổ đúng chi nhánh.</p></div></div><div class="rec" style="margin-top:20px"><span>03</span><div><b>Ghi sổ & truy vết</b><p>Phân quyền duyệt, lưu chứng từ gốc và lịch sử thay đổi trong bản triển khai thật.</p></div></div></div></div><div class="card" style="margin-top:20px"><div class="card-head"><h2>Giao dịch đã nhập trên thiết bị</h2><button class="outline" id="exportInvoices">↓ CSV giao dịch</button></div><div class="table-wrap"><table><thead><tr><th>Mã</th><th>Ngày</th><th>Chi nhánh</th><th>Loại</th><th>Số tiền</th></tr></thead><tbody id="invoiceRows"></tbody></table></div></div>`}
function safe(v){return String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}function invoiceRows(){$('#invoiceRows').innerHTML=invoices.length?invoices.map(x=>`<tr><td data-i18n-skip>${safe(x.id)}</td><td>${safe(I18n.date(x.date))}</td><td data-i18n-skip>${safe(x.branch)}</td><td>${safe(x.type)}</td><td>${fmt(x.amount)} ₫</td></tr>`).join(''):'<tr><td colspan="5">Chưa có giao dịch. Hãy thử nhập hóa đơn đầu tiên.</td></tr>'}
function research(){return `<div class="two"><div class="card"><h2>Thành phần mã nguồn mở đã kiểm tra</h2><a class="source" href="https://github.com/frappe/erpnext" target="_blank" rel="noopener"><b>01 / ERPNext ↗</b><p>Kế toán, hóa đơn, kho, nhà cung cấp, quản lý tài sản. Phù hợp làm nền tảng nghiệp vụ phía máy chủ.</p><small>Đã đọc README trực tiếp trên GitHub · cần đánh giá giấy phép khi tích hợp</small></a><a class="source" href="https://github.com/google/or-tools" target="_blank" rel="noopener"><b>02 / Google OR-Tools ↗</b><p>Tối ưu tuyến tính, số nguyên và CP-SAT. Ứng dụng cho lịch làm, đặt hàng và phân bổ nguồn lực có ràng buộc.</p><small>Đã đọc README trực tiếp · Apache 2.0</small></a><div class="insight">Demo tự xây để kiểm chứng trải nghiệm và công thức. Chưa cài ERPNext hoặc OR-Tools; không tuyên bố tối ưu toàn cục.</div></div><div class="card"><h2>Lộ trình đạt chất lượng vận hành chuyên nghiệp</h2>${[['01','Nền tảng tài chính','Sổ kép, hệ thống tài khoản, chốt kỳ, tồn kho, khấu hao, thuế, dòng tiền và hợp nhất chi nhánh.'],['02','Dữ liệu & kiểm soát','POS/OCR, xác nhận chứng từ, phân quyền, nhật ký kiểm toán, sao lưu và khôi phục.'],['03','Dự báo & tối ưu','Dữ liệu theo ngày, mô hình mùa vụ, kiểm định theo thời gian; ràng buộc chất lượng, nhân sự và công suất bếp.'],['04','Vận hành sản phẩm','Đăng nhập, cơ sở dữ liệu máy chủ, kiểm thử bảo mật, giám sát, đối soát kế toán và nguồn giá có hợp đồng.']].map(x=>`<div class="rec" style="margin-top:23px"><span>${x[0]}</span><div><b>${x[1]}</b><p>${x[2]}</p></div></div>`).join('')}<p class="muted">Một demo giao diện chưa tương đương hệ thống tài chính đã kiểm toán. Các số hiện tại không dùng để lập báo cáo thuế.</p></div></div>`}
function download(name,rows){rows=rows.map((row,i)=>row.map((value,j)=>typeof value==='string'&&((name==='bep-bao-cao-demo.csv'&&(j===0||i===3||(i===2&&j===1)))||(name==='bep-giao-dich-demo.csv'&&i===0))?I18n.t(value):value));const csv='\uFEFF'+BepCSV.serialize(rows);let a=document.createElement('a');a.href=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
function render(){const names={overview:'Tổng quan',costs:'Chi phí & mặt bằng',simulate:'Mô phỏng lợi nhuận',forecast:'Dự báo kinh doanh',market:'Thị trường nguyên liệu',invoices:'Sổ giao dịch',research:'Nền tảng & phương pháp'};$('#pageTitle').textContent=titles[tab][0];$('#subtitle').textContent=titles[tab][1];$('#crumb').textContent=names[tab];document.querySelectorAll('nav button').forEach(x=>x.classList.toggle('active',x.dataset.tab===tab));$('#app').innerHTML=({overview,costs,simulate,forecast,market:marketView,invoices:invoicesView,research})[tab]();document.querySelectorAll('[data-go]').forEach(x=>x.onclick=()=>{tab=x.dataset.go;render()});if(tab==='simulate'){updateSim();document.querySelectorAll('[data-scenario]').forEach(x=>x.oninput=()=>{scenario[x.id]=+x.value;$('#'+x.id+'Val').textContent=fmt(+x.value,1)+(x.id==='rent'?' triệu ₫':'%');updateSim()});$('#reset').onclick=()=>{scenario={price:0,volume:0,food:0,labor:0};render()};$('#saveScenario').onclick=()=>{try{localStorage.setItem('bep-scenario',JSON.stringify({branch:$('#branch').value,scenario}));toast('Đã lưu kịch bản trên thiết bị này.')}catch{toast('Trình duyệt không cho phép lưu dữ liệu.')}};$('#loadScenario').onclick=()=>{try{let x=JSON.parse(localStorage.getItem('bep-scenario'));if(!x)return toast('Chưa có kịch bản đã lưu.');$('#branch').value=x.branch;scenario=x.scenario;render();toast('Đã mở kịch bản đã lưu.')}catch{toast('Không thể đọc kịch bản đã lưu.')}}}if(tab==='forecast'){updateForecast();$('#forecastMode').onchange=updateForecast}if(tab==='market'){const change=v=>{market=v;render()};$('#marketSelect').onchange=e=>change(e.target.value);document.querySelectorAll('[data-city]').forEach(x=>x.onclick=()=>change(x.dataset.city))}if(tab==='invoices'){invoiceRows();$('#invoiceForm').onsubmit=e=>{e.preventDefault();let id=$('#invoiceName').value.trim();if(!id)return toast('Vui lòng nhập mã hóa đơn.');let branch=$('#invoiceBranch').value;if(invoices.some(x=>x.id===id&&x.branch===branch))return toast('Mã hóa đơn đã tồn tại tại chi nhánh này.');let x={id,branch,date:$('#invoiceDate').value,type:$('#invoiceType').value,amount:+$('#invoiceAmount').value};let next=[...invoices,x];try{localStorage.setItem('bep-invoices',JSON.stringify(next));invoices=next;invoiceRows();$('#invoiceForm').reset();$('#invoiceDate').value='2026-11-08';toast('Đã lưu. Giao dịch thử nghiệm chưa cộng vào báo cáo.')}catch{toast('Không lưu được: bộ nhớ thiết bị không khả dụng.')}};$('#exportInvoices').onclick=()=>download('bep-giao-dich-demo.csv',[['Mã','Ngày','Chi nhánh','Loại','Số tiền VND'],...invoices.map(x=>[x.id,x.date,x.branch,x.type,x.amount])])}}
document.querySelectorAll('nav button').forEach(x=>x.onclick=()=>{tab=x.dataset.tab;render()});$('#branch').onchange=()=>{scenario.rent=undefined;render()};$('#export').onclick=()=>{let b=base(),r=Finance.calc(b),s=Finance.calc(b,scenario);download('bep-bao-cao-demo.csv',[['BẾP FINANCE - DỮ LIỆU MINH HỌA'],['Chi nhánh',$('#branch').selectedOptions[0].text],['Đơn vị','Triệu VND'],[I18n.t('Chỉ số'),I18n.t('Hiện tại'),I18n.t('Kịch bản')],['Doanh thu',r.revenue,s.revenue],['Nguyên liệu',r.food,s.food],['Nhân sự',r.labor,s.labor],['Thuê mặt bằng',r.rent,s.rent],['Chi phí khác',r.other,s.other],['Lợi nhuận vận hành trước khấu hao, lãi vay, thuế',r.profit,s.profit],['Biên lợi nhuận %',r.margin,s.margin],['Ghi chú','Giao dịch nhập tay chưa đưa vào báo cáo; không phải dự báo được huấn luyện.']]);toast('Đã xuất báo cáo CSV. Đơn vị: triệu VND.')};render();
